window.__CAT__=window.__CAT__||[];window.__CAT__.push([{"no": 141, "id": "0FavmQbdtPI", "title": "【Lの女性向音声】帮忙照顾姐姐家的小朋友（暖心哄睡向）", "title_zh": "帮忙照顾姐姐家的小朋友（暖心哄睡向）", "duration": "00:07:39", "link": "https://www.youtube.com/watch?v=0FavmQbdtPI", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我又又不接了。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:00:01-00:00:09", "text": "我都不接了（重复5次，已合并）。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:11", "text": "睡了吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:15", "text": "睡着了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:18", "text": "真的睡着了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:28", "text": "终于安静了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:32", "text": "你看看这个小脸。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:37", "text": "现在想到这么个乖乖睡觉的小宝宝。", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:00:41", "text": "闹起来的时候能把屋顶给卸饭吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:46", "text": "你说去一个小家伙怎么能吃饭呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:54", "text": "你知道吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:56", "text": "想吃饭。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:59", "text": "你知道吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:01:02", "text": "想我那会儿。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:05", "text": "要不是你拦着。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:08", "text": "我正于一种就是。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:11", "text": "烦了毁灭吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:14", "text": "的想法。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:17", "text": "哎呀不过呀！", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:01:19", "text": "没想到我的宝宝。", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:01:22", "text": "当起小就妈来。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "一挺像样的吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:01:28", "text": "把我平时照顾你那套许晓惠了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "我平时怎么照顾你的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "心情抱抱几个个啊吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:01:38", "text": "对我干嘛？", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:01:41", "text": "没事。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:01:45", "text": "想起来我不是睡了吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:01:48", "text": "我们就可以啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "啊不得你不得你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:55", "text": "不过说起来好。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:01:59", "text": "宝宝已经接受小就妈的生活了。", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:02:03", "text": "之前啊小鬼头叫你小就妈的时候。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:07", "text": "你比他还小。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "又解放我后面多呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:02:17", "text": "今天都可以有你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "小朋友玩得很开心啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:25", "text": "不然的话。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:27", "text": "还是要换着回家。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "要找妈妈。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:32", "text": "托你的父。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "那当然啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:37", "text": "我二人们感谢你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "就是因为我你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:43", "text": "姐姐姐父才能在几回今年日之铁。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:46", "text": "过一国就位的二人世界。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:48", "text": "然后明天我告诉她。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:51", "text": "我们俩天天都是什么过的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:54", "text": "羡慕吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:57", "text": "你还觉得今天挺开心的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:59", "text": "其实我看出来了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "从这个小鬼头到咱们家。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:05", "text": "你一整天都乐和合的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "还陪她看动画片。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:10", "text": "把她准备天底。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:13", "text": "陪她玩玩剧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:15", "text": "就连大饭牛奶都把她手饰。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:18", "text": "还为她吃饭。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "让我看看。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "我的宝宝是不是笑得脸都快着急了。", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:03:35", "text": "你说这个小孩是从哪儿学来的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:39", "text": "居然还会给你送花。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:03:43", "text": "对啊我听姐说。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "从昨天晚上。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "她就一直念到这。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:49", "text": "来咱们家之前。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "要先去到花店。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "但是后来到花店。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:57", "text": "似乎我看上了合花。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "谁说也不听？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:05", "text": "真的是。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:07", "text": "你又不是那个账。", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:04:09", "text": "对不对？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:12", "text": "而且你说这。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:14", "text": "一线苏的审美。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:17", "text": "怎么看都不像一传我们家？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:19", "text": "她说是因为合花里没有脸子。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:22", "text": "你要按这个小子脑回路。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:26", "text": "我觉得小子他应该送你家相日盔。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:31", "text": "你什么眼神。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "我是送过你相日盔。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:39", "text": "但我是因为花好看。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:43", "text": "我瓜子没有关系。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:48", "text": "我让你笑。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:04:53", "text": "再说了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:58", "text": "你不是挺喜欢相日盔的吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:05:03", "text": "我什么时候又说嫂话了？", "speaker": "他", "tone": "责备", "sound": []}, {"ts": "00:05:07", "text": "你脑子里面总有一些。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:11", "text": "继续怪怪的想法吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:15", "text": "一。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:19", "text": "小东西睡觉也不老实。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:24", "text": "你说她这么大个小人。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:29", "text": "刚才居然还想让我的宝贝帮她洗澡。", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:05:35", "text": "还在那儿装哭。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:05:39", "text": "还在那儿承计抱你的腿。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:43", "text": "我姐怎么讲出这么个戏境来。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:47", "text": "这几天我好好娇育娇育她。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:52", "text": "那是。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:56", "text": "就是两天也是能体会服务的不容易啊！", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:06:03", "text": "我记得宝贝曾经说过。", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:06:08", "text": "小时候是在白婆家长大的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:12", "text": "父母都忙着工作经常见不到面。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:16", "text": "你想那么？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "也不敢告诉我一波。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:24", "text": "就在背子里面。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:28", "text": "头头哭。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:06:32", "text": "与一次好不容易见到了。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:06:36", "text": "又对抱抱妈妈发脾气。", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:06:40", "text": "还把他们给你买的玩具。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:44", "text": "给扔了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:48", "text": "后来还一直很刺色。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:52", "text": "所以看到小贵头的时候。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:56", "text": "就想接小时候自己。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:00", "text": "也是平面对他好。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:04", "text": "就是感觉我的宝贝。", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:07:08", "text": "长大了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:12", "text": "什么想留下老父亲的眼泪过来？", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:07:20", "text": "好了不走了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:23", "text": "睡觉。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:26", "text": "保持你们俩睡。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:26", "text": "明天早上我来做。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:26", "text": "你安心睡吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:26", "text": "今天忙了一天了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:26-00:07:26", "text": "不怕。", "speaker": "他", "tone": "温柔", "sound": []}], "scene": "暖心日常向。一对伴侣临时帮忙照看姐姐家的小朋友，男生温柔夸赞女生把「小舅妈」当得有模有样，聊起孩子送她花、她一整天的开心，并在孩子睡后安抚女生、准备让她安心休息。基调温馨宠溺、日常哄睡，无管娇或露骨情节。", "behaviors": [{"desc": "确认小朋友终于睡着，调侃其闹腾与乖巧的反差"}, {"desc": "夸女生当「小舅妈」像样，把被照顾的那套用在了孩子身上"}, {"desc": "提及姐姐姐夫得以过二人世界，女生也乐在其中"}, {"desc": "聊起小朋友去花店挑花送她，审美逗趣"}, {"desc": "说起孩子想让女生帮忙洗澡、撒娇抱腿的趣事"}, {"desc": "女生回忆自己童年缺少陪伴，因此对小孩格外温柔"}, {"desc": "孩子睡后，对方让女生安心休息，承诺明早由他来做"}], "tone_summary": "（自动）他视角独白，语气以平静、询问、撒娇为主，题材偏治愈。", "genre_tags": ["治愈"], "genre_main": "治愈/宠溺", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "电话响了好几次，他摸黑接起来，压低声音哄了几句，又轻手轻脚地挂断，转头看向床边的小床。"}, {"type": "line", "speaker": "他", "text": "又哭了？不哭了不哭了。睡了吗？睡着了。真的睡着了。终于安静了。"}, {"type": "narr", "text": "他弯腰凑近，看着小床里那张睡熟的小脸，忍不住笑了。"}, {"type": "line", "speaker": "他", "text": "你看看这个小脸，现在想到这么个乖乖睡觉的小宝宝，闹起来的时候能把屋顶给掀翻吗？你说这么一个小家伙，怎么能这么能闹呢？"}, {"type": "line", "speaker": "他", "text": "你知道吗？想那时候，要不是你拦着，我真的是——烦了，毁灭吧的想法。"}, {"type": "narr", "text": "他坐到她身边，眼睛亮晶晶的，带着点骄傲地打量她。"}, {"type": "line", "speaker": "他", "text": "哎呀，不过呀，没想到我的宝宝当起小舅妈来，还挺像样的嘛。把我平时照顾你那套都学去了。"}, {"type": "line", "speaker": "他", "text": "我平时怎么照顾你的？心情抱抱举高高啊？对我干嘛？没事，想起来我是不是赚了。我们就可以啊——哎呀，不不不。"}, {"type": "narr", "text": "他笑着摆手，又看了一眼小床，压低声音说："}, {"type": "line", "speaker": "他", "text": "不过说起来，宝宝已经接受小舅妈的生活了。之前啊，小鬼头叫你小舅妈的时候，你还比他还害羞，躲在我后面呢。今天都可以有你，小朋友玩得很开心啊！"}, {"type": "line", "speaker": "他", "text": "不然的话，还是要哭着回家，要找妈妈。托你的福，那当然啊！我二人们感谢你。就是因为有你，姐姐姐夫才能在时隔今年，过一次久违的二人世界。"}, {"type": "narr", "text": "他絮絮叨叨说着，忽然偏过头认真看她。"}, {"type": "line", "speaker": "他", "text": "然后明天我告诉她，我们俩天天都是怎么过的，羡慕吧。你还觉得今天挺开心的。其实我看出来了，从这个小鬼头到咱们家，你一整天都乐呵呵的。"}, {"type": "line", "speaker": "他", "text": "还陪她看动画片，给她准备甜点，陪她玩玩具，就连大饭牛奶都帮她试温，还喂她吃饭。让我看看，我的宝宝是不是笑得脸都快着急了。"}, {"type": "narr", "text": "她不好意思地抿嘴笑，他伸手刮了刮她的鼻尖，语气又软又宠。"}, {"type": "line", "speaker": "他", "text": "你说这个小孩是从哪儿学来的，居然还会给你送花。对啊，我听姐说，从昨天晚上她就一直念着，来咱们家之前，要先去趟花店。"}, {"type": "narr", "text": "他学着小孩的语气，声音里带着笑意。"}, {"type": "line", "speaker": "他", "text": "但是后来到了花店，似乎她看上了荷花，谁说也不听。真的是。你又不是那个荷花，对不对？而且你说这，一小束的审美，怎么看都不像一传我们家？"}, {"type": "line", "speaker": "他", "text": "她说是因为荷花里没有莲子。你要按这个小子的脑回路，我觉得小子他应该送你向日葵。你什么眼神？我是送过你向日葵，但我是因为花好看，跟瓜子没有关系。"}, {"type": "line", "speaker": "他", "text": "我让你笑。再说了，你不是挺喜欢向日葵的吗？我什么时候又说过坏话了？你脑子里面总有一些奇奇怪怪的想法吧。"}, {"type": "narr", "text": "小床上的人儿翻了个身，踢掉了被子。他走过去替她盖好，低声笑着摇头。"}, {"type": "line", "speaker": "他", "text": "小东西睡觉也不老实。你说她这么大个小人，刚才居然还想让我的宝贝帮她洗澡，还在那儿装哭，还在那儿趁机抱你的腿。我姐怎么养出这么个戏精来。"}, {"type": "line", "speaker": "他", "text": "这几天我好好教育教育她。那是。就这两天，也是能体会当妈的不容易啊！"}, {"type": "narr", "text": "他声音忽然轻下来，目光落在她脸上，带着深深的疼惜。"}, {"type": "line", "speaker": "他", "text": "我记得宝贝曾经说过，小时候是在外婆家长大的，父母都忙着工作，经常见不到面。想他们了，也不敢告诉外婆，就在被子里面偷偷哭。"}, {"type": "narr", "text": "他握住她的手，声音更轻了几分。"}, {"type": "line", "speaker": "他", "text": "好不容易见到了，又对抱抱妈妈发脾气，还把他们给你买的玩具给扔了。后来还一直很自责。所以看到小鬼头的时候，就想起了小时候的自己，也是拼命对她好。"}, {"type": "line", "speaker": "他", "text": "就是感觉，我的宝贝，长大了。什么？想留下老父亲的眼泪了？"}, {"type": "narr", "text": "她眼眶有些红，他伸手把她揽进怀里，轻轻拍她的背。"}, {"type": "line", "speaker": "他", "text": "好了不走了。睡觉。保持你们俩睡。明天早上我来做。你安心睡吧，今天忙了一天了。不怕。"}, {"type": "narr", "text": "夜安静下来，小床上的孩子睡得香甜，他也搂着她，像守着全世界最珍贵的两件宝贝，合上了眼。"}]}, {"no": 142, "id": "S9RkXGDrolY", "title": "【Lの女性向音声】年度报告被发现", "title_zh": "年度报告被发现", "duration": "00:05:43", "link": "https://www.youtube.com/watch?v=S9RkXGDrolY", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我回来了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:02", "text": "刚刚路过甜品店，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:05", "text": "给你买了一个草莓塔。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:08", "text": "快过来吃。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:11", "text": "等什么呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:00:14", "text": "你干嘛呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:00:18", "text": "手机投屏到电视看美剧啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:22", "text": "还挺会玩的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "那我就好——", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:38", "text": "那我就换个衣服过来和你一起看。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:50", "text": "小家伙一上厕所，投屏没关啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "这是……", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:58", "text": "2022年度报告。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:03", "text": "回来了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:06", "text": "来来来，你过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:10", "text": "你就不知道投屏忘关了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "哎呦。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:17", "text": "我宝宝看的东西还真是精彩。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:01:19", "text": "正装杀。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "西装男。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:23", "text": "手控。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "腿控。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:27", "text": "女性向。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:29", "text": "声控男友。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:32", "text": "以前都没发现，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "我家小狗这么饥渴啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:37", "text": "安静。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "我还没说完呢。", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:01:43", "text": "发布这么多评论，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:46", "text": "点了这么多赞，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "不是夸别人好听，", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:51", "text": "就是发花痴。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:54", "text": "还说没有？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:57", "text": "那这个——", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:00", "text": "帅哥，你这组图片光线打得不对。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:03", "text": "哥哥，为我详细讲解一下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:06", "text": "这是评论？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:09", "text": "跪得倒挺快啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "我还是喜欢你之前的样子。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:02:20", "text": "来，你告诉我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "那些标签，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:28", "text": "哪个不是天花板？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:32", "text": "他们哪个比我强？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:36", "text": "既然这样，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:39", "text": "那你还去看那些博主？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:43", "text": "哎，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:46", "text": "帅哥加个微信，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "详细说说。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:54", "text": "准备说什么？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:57", "text": "准备告诉他们，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:01", "text": "你是怎么被我收拾的吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:03:05", "text": "怎么了？被外面的野花吓到了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:12", "text": "是真的被吓到了，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:17", "text": "还是想逃避惩罚？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:23", "text": "这拿你没办法。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "好好好，主人抱着，抱着抱着。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:33", "text": "跟主人说说，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:36", "text": "为什么看得这么起劲？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:40", "text": "虽然不想承认，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "但确实还是有点吃醋的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:48", "text": "怪我工作忙，没时间陪你。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:03:56", "text": "可能今年事情会多一些，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "陪你时间有点少了吧。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:04:03", "text": "那哥哥答应你，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:06", "text": "等放假了，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "过年的时候陪你出去玩，好不好？", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:13", "text": "我当然知道你说那些话，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:17", "text": "都是口嗨。", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:04:21", "text": "就你嘴甜。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "好了好了，知道了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:27", "text": "你这点小爱好，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:30", "text": "我还能不知道啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:33", "text": "这只是我看到的一部分，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:36", "text": "谁知道你还对多少人，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:39", "text": "说过这些虎狼之词。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:42", "text": "没有。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "真的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:49", "text": "瞒不住了吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:54", "text": "我也没想限制你这些，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:58", "text": "但我们要有个度，对不对？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:03", "text": "乖。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:05:07", "text": "把草莓塔吃了吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:12", "text": "一会儿该化了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:18", "text": "看你，都弄到脸上了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:24", "text": "哥哥给擦擦。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:30", "text": "怎么样，好不好吃啊？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:05:35", "text": "那我也尝尝。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:40", "text": "是挺甜的。", "speaker": "哥哥", "tone": "平静", "sound": []}], "scene": "日常情侣向。男生回家发现女生把手机投屏到电视看剧，意外看到她的年度听单与评论，发现她偏好「女性向音声/正装杀/西装男」等内容并关注相关博主；他半开玩笑地吃醋追问，最终以拥抱与喂草莓塔化解，约定假期陪伴。基调轻松调情、带点占有欲的宠溺，无露骨情节。", "behaviors": [{"desc": "男生带回草莓塔，发现女生把手机投屏看剧"}, {"desc": "瞥见她的年度听单与评论，调侃其偏好女性向内容"}, {"desc": "半开玩笑吃醋，问她为何关注别的博主"}, {"desc": "揽她入怀，承认自己因工作忙少陪伴、有点醋意"}, {"desc": "承诺过年放假陪她出去玩，包容她的小爱好"}, {"desc": "喂她吃草莓塔并擦脸，以亲密互动收尾"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、命令、询问为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "治愈"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "门锁转动，他拎着一盒甜品进门，语气轻快。客厅里没有回应，只有电视上美剧的声音。他探头一看，她已经不在沙发上了。"}, {"type": "line", "speaker": "哥哥", "text": "我回来了。刚刚路过甜品店，给你买了一个草莓塔。快过来吃。等什么呢？你干嘛呢？手机投屏到电视看美剧啊！还挺会玩的。"}, {"type": "narr", "text": "他放下甜品，打算回屋换衣服。经过茶几时，脚步却忽然顿住了——电视屏幕上，投屏画面已经切换，是一份年度报告。"}, {"type": "line", "speaker": "哥哥", "text": "那我就换个衣服过来和你一起看。小家伙一上厕所，投屏没关啊！这是……2022年度报告。"}, {"type": "narr", "text": "他坐回沙发上，饶有兴致地看了起来。她听见声音，慌慌张张从卫生间跑出来，正想关掉投屏，却被他伸手拦住。"}, {"type": "line", "speaker": "哥哥", "text": "回来了。来来来，你过来。你就不知道投屏忘关了。哎呦。我宝宝看的东西还真是精彩。"}, {"type": "narr", "text": "屏幕上的年度标签逐条滚动。她的脸一点点涨红，恨不得找个地缝钻进去。他却念得慢条斯理。"}, {"type": "line", "speaker": "哥哥", "text": "正装杀。西装男。手控。腿控。女性向。声控男友。以前都没发现，我家小狗这么饥渴啊！"}, {"type": "narr", "text": "她张了张嘴想解释，被他一个眼神制止。他抬了抬下巴，示意她看屏幕，继续念下去。"}, {"type": "line", "speaker": "哥哥", "text": "安静。我还没说完呢。发布这么多评论，点了这么多赞，不是夸别人好听，就是发花痴。还说没有？"}, {"type": "line", "speaker": "哥哥", "text": "那这个——帅哥，你这组图片光线打得不对。哥哥，为我详细讲解一下。这是评论？"}, {"type": "narr", "text": "她腿一软，扑通跪了下去，声音都在发抖。他看着跪在地上的她，语气带着点玩味。"}, {"type": "line", "speaker": "哥哥", "text": "跪得倒挺快啊！我还是喜欢你之前的样子。来，你告诉我。那些标签，哪个不是天花板？他们哪个比我强？"}, {"type": "narr", "text": "她跪在原地，小声说，你最好。他却没有放过她的意思，反而翻出她发给别人的私信。"}, {"type": "line", "speaker": "哥哥", "text": "既然这样，那你还去看那些博主？哎，帅哥加个微信，详细说说。准备说什么？准备告诉他们，你是怎么被我收拾的吗？"}, {"type": "narr", "text": "她眼眶一下子红了，垂下头不说话。他看着她这副模样，心忽然软了，叹了口气，把人从地上捞起来抱进怀里。"}, {"type": "line", "speaker": "哥哥", "text": "怎么了？被外面的野花吓到了？是真的被吓到了，还是想逃避惩罚？这拿你没办法。好好好，主人抱着，抱着抱着。"}, {"type": "narr", "text": "她埋在他怀里，闷闷地说，怕你不要我了。他轻轻拍了拍她的背，语气带着无奈和心疼。"}, {"type": "line", "speaker": "哥哥", "text": "跟主人说说，为什么看得这么起劲？虽然不想承认，但确实还是有点吃醋的。怪我工作忙，没时间陪你。"}, {"type": "line", "speaker": "哥哥", "text": "可能今年事情会多一些，陪你时间有点少了吧。那哥哥答应你，等放假了，过年的时候陪你出去玩，好不好？"}, {"type": "narr", "text": "她从他怀里抬起头，眼睛亮了一下。他捏了捏她的脸，语气带着纵容。"}, {"type": "line", "speaker": "哥哥", "text": "我当然知道你说那些话，都是口嗨。就你嘴甜。好了好了，知道了。你这点小爱好，我还能不知道啊！"}, {"type": "narr", "text": "他顿了顿，又故意拖长了声音。她立刻紧张起来。"}, {"type": "line", "speaker": "哥哥", "text": "这只是我看到的一部分，谁知道你还对多少人，说过这些虎狼之词。没有。真的。瞒不住了吧？"}, {"type": "narr", "text": "她在他怀里拼命摇头，说只对你一个人说过。他低头看她，笑意终于漫上来，语气放软。"}, {"type": "line", "speaker": "哥哥", "text": "我也没想限制你这些，但我们要有个度，对不对？乖。把草莓塔吃了吧。一会儿该化了。"}, {"type": "narr", "text": "她听话地拿起草莓塔，小口小口吃着。他坐在旁边看她，忽然伸手，拇指擦过她嘴角的奶油。"}, {"type": "line", "speaker": "哥哥", "text": "看你，都弄到脸上了。哥哥给擦擦。怎么样，好不好吃啊？那我也尝尝。是挺甜的。"}, {"type": "narr", "text": "他顺势低头，亲了亲她沾着奶油的嘴角。她脸一红，把草莓塔往他嘴边递。窗外的天色渐晚，客厅里暖融融的。这一场年度报告的审问，最后化成了一整个草莓塔的甜。"}]}, {"no": 143, "id": "rXWoo-7y-Yo", "title": "【Lの女性向音声】当你海棠作者的身份被抖s男友发现", "title_zh": "当你海棠作者的身份被施虐系男友发现", "duration": "00:09:20", "link": "https://www.youtube.com/watch?v=rXWoo-7y-Yo", "enriched": true, "lines": [{"ts": "00:00:00", "text": "写了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:10", "text": "我老婆写完早真香。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "painted。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:20", "text": "这里有个问题想请娇你一下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:26", "text": "我真的想一起做。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "洗完了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:34", "text": "我前几天帮你修电脑的时候发现一个不得了的连接。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:38", "text": "你让我宝贝还会看海桃稳呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:00:42", "text": "你吹我干嘛？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:00:46", "text": "我不是不让你看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "多看看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "说不定还能让我够舒服一些呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:00:58", "text": "你过来过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:02", "text": "就是处于好奇好看你主意。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:06", "text": "我发现你不吃看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:10", "text": "还会写呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:01:14", "text": "然后呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:01:18", "text": "我就顺疼摩花的找到了你的微博。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:01:22", "text": "好不是你的好朋友的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:26", "text": "朋友的你二头红什么？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:30", "text": "然后我就顺便把你朋友的写的文都大概读了一遍。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "没想到还有这么个朋友。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "我家小姑娘怎么中鞭胎我些这种东西。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "怎么都不和哥哥说一声？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:46", "text": "脑袖承诺开始咬人了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:50", "text": "那真的是朋友的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:54", "text": "那为什么微博上面晒的那个礼物是我之前送给你的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:58", "text": "配完是怎么办男朋友。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "哎呀怎么哭了？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:02:06", "text": "不哭了不哭了。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:10", "text": "不哭了。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:14", "text": "都你的都你的好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:02:18", "text": "没有觉得你变难。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:22", "text": "应该说好变态我好喜欢。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:02:26", "text": "好啊怪猫猫头。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "那个怪。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:34", "text": "不知道想白我吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:38", "text": "怎么不干了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:42", "text": "我还有你白啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:46", "text": "是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "啊什么？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:54", "text": "本来我想给你慢慢来的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:58", "text": "但是现在看的话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "还是要加快点进度。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:06", "text": "所以今天我就带你时间一下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:10", "text": "毕竟写了这么多理论。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:14", "text": "也该让你体验体验了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:18", "text": "理论结合时间才能写得够好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "对不对？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:26", "text": "东西早就给你准备好了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:30", "text": "去玩那边那个铁皮盒子拿过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:34", "text": "你马上一生日。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "选一个你喜欢的。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:03:41", "text": "连怎么这么红啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "不想自己选。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:49", "text": "也是。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "小姑娘第一次总会害羞的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:56", "text": "所以就让我这个主人带牢你一下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:00", "text": "就这个吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:04", "text": "腾条。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:08", "text": "不要。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:12", "text": "现在可以又不得你了。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:04:18", "text": "瞧你本区的样子。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:21", "text": "腾条不要的话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "那就。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:27-00:04:30", "text": "就。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:33", "text": "继续吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:36", "text": "也挺有分为感的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:39", "text": "姿势摆好了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "微微扭扭的什么姿势。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:50", "text": "小说起来跟老手一样。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:54", "text": "结果做起来什么都不懂。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:59", "text": "前几天是哪个小朋友。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "大半夜头和了大半头酸奶。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:13", "text": "错哪了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:21", "text": "叫我什么？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:26", "text": "不对。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:30", "text": "重新叫人。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:34", "text": "叫不出来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:37", "text": "你小说你写得出来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:40", "text": "到我这里你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:43", "text": "叫不出来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:46", "text": "不快点做的话。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:49", "text": "身体可叫糟罪了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:53", "text": "叫大声点。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:58", "text": "这还差不多。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:06", "text": "所以就这几下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:11", "text": "下面就留出来这么多了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:16", "text": "哥哥帮你擦一擦。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:22", "text": "衣服多了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:28", "text": "各位家小姑娘。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:34", "text": "戴上眼罩和小铃铛。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:40", "text": "顺于事证转一切。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:44", "text": "意识证再擦一切。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:49", "text": "上下左右都不能放过。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:53", "text": "都得擦一擦。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:58", "text": "宝贝怎么越擦睡越多。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:07:02", "text": "而且。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:06", "text": "有点种了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:11", "text": "哥哥帮你把睡读住好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:07:15", "text": "掌握身体。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:19", "text": "轨盘好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:24", "text": "眼睛被盟主。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:27", "text": "反正比平时更敏感了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:31", "text": "所以。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:35", "text": "下词。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:38", "text": "哥哥一边调娇你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:42", "text": "你就一边把它写成小说。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:46", "text": "写不完不准听。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:07:49", "text": "这样写出来的才更加真实。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:53", "text": "你说好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:07:57", "text": "小骄傲。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:06", "text": "小骄傲起宝。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:11", "text": "这就受不了了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:16", "text": "不可能的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:21", "text": "怎么会这么容易放过你？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:27", "text": "谁？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:28", "text": "love。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:29", "text": "me。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:30", "text": "谁？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:31", "text": "love。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:32", "text": "me。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:34", "text": "就谁？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:35", "text": "love。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:36", "text": "me。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:37", "text": "谁？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:38", "text": "love。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:39", "text": "me。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:41", "text": "谁？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:42", "text": "love。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:43", "text": "me。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:44", "text": "谁？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:45", "text": "love。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:46", "text": "me。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:48", "text": "帮你去洗澡。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:53", "text": "生气了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:53", "text": "不是很气。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:53", "text": "谁让我家宝贝味道太好了？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:08:53", "text": "对不对？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:53", "text": "而且以前走得动路。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:53", "text": "总不能凝糊糊的睡觉。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:53", "text": "来吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:53", "text": "关到宝贝沙。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:08:53", "text": "把我家的小猪猪去洗澡。", "speaker": "哥哥", "tone": "平静", "sound": []}], "scene": "日常情侣向（虚构角色扮演）。男生帮女生修电脑时发现她以「海棠作者」身份写女性向小说，顺着线索读到她的作品，既惊喜又调侃；随后以「主人」身份带她体验文中描写的情节，要求她把感受写成小说，并事后帮她洗澡安抚。基调是「创作爱好被发现+角色扮演互动」，含轻度管娇与亲密互动元素。纯虚构剧情。", "behaviors": [{"desc": "男生发现她撰写海棠文，顺势读到她的社交动态与作品"}, {"desc": "让她从盒中自选道具，因害羞代为挑选其一"}, {"desc": "要求摆好姿势，开始角色扮演管娇环节"}, {"desc": "纠正她对「主人」的称呼，要求大声唤出"}, {"desc": "给她戴眼罩与小铃铛，引导边体验边把感受写成小说"}, {"desc": "结束后帮她洗澡并安抚收尾"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、撒娇、命令为主，题材偏古风。", "genre_tags": ["古风", "主仆/调教"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": ["鞭"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "他靠在书房门口，手里晃着手机，慢悠悠地开口，语气里带着藏不住的笑意。"}, {"type": "line", "speaker": "哥哥", "text": "写了。我老婆写完啦，真香。"}, {"type": "narr", "text": "她正对着电脑屏幕，被他这一句吓得差点跳起来。他走过来，把手机屏幕转向她。"}, {"type": "line", "speaker": "哥哥", "text": "painted。这里有个问题想请教你一下，我真的想一起做。洗完了？"}, {"type": "narr", "text": "她还没反应过来，他已经点开了浏览器历史记录。"}, {"type": "line", "speaker": "哥哥", "text": "我前几天帮你修电脑的时候，发现一个不得了的链接。你让我看看，我家宝贝还会看海棠文呢？你捶我干嘛？我不是不让你看。多看看，说不定还能让我更舒服一些呢？"}, {"type": "narr", "text": "她耳根烧起来，伸手想抢电脑，被他一把捞进怀里，下巴搁在她头顶。"}, {"type": "line", "speaker": "哥哥", "text": "你过来过来。就是出于好奇，看了看你主意。我发现你不只看，还会写呢？然后呢？我就顺藤摸瓜，找到了你的微博。还不是你的好朋友的？朋友？你耳朵红什么？"}, {"type": "line", "speaker": "哥哥", "text": "然后我就顺便把你朋友写的文，都大概读了一遍。没想到还有这么个朋友。我家小姑娘怎么看这些这种东西？怎么都不和哥哥说一声？"}, {"type": "line", "speaker": "她", "text": "那真的是朋友的……"}, {"type": "line", "speaker": "哥哥", "text": "那为什么，微博上面晒的那个礼物，是我之前送给你的？配文是“怎么办男朋友”。"}, {"type": "narr", "text": "她张了张嘴，眼眶一下子就红了。他愣了一下，手忙脚乱地替她擦脸。"}, {"type": "line", "speaker": "哥哥", "text": "哎呀怎么哭了？不哭了不哭了。都你的，都你的好不好？没有觉得你变态。应该说——好变态，我好喜欢。"}, {"type": "line", "speaker": "哥哥", "text": "好了，乖猫猫头，别哭了。知道错了吗？怎么不吭声了？我还没跟你算账呢，是不是？"}, {"type": "narr", "text": "她抽抽噎噎地点头。他眼神暗了暗，声音放低。"}, {"type": "line", "speaker": "哥哥", "text": "本来我想给你慢慢来的，但是现在看的话，还是要加快点进度。所以今天，我就带你实践一下。毕竟写了这么多理论，也该让你体验体验了。理论结合实践，才能写得够好。对不对？"}, {"type": "line", "speaker": "哥哥", "text": "东西早就给你准备好了。去那边那个铁皮盒子拿过来。马上要生日了，选一个你喜欢的。脸怎么这么红啊？不想自己选？也是，小姑娘第一次总会害羞的。"}, {"type": "line", "speaker": "哥哥", "text": "所以就让我这个主人带带你。就这个吧，藤条。不要？现在，可由不得你了。瞧你这别扭的样子。"}, {"type": "narr", "text": "她咬着唇别开脸。他把藤条在手里掂了掂，语气懒洋洋的。"}, {"type": "line", "speaker": "哥哥", "text": "藤条不要的话，那就……继续吧。也挺有氛围感的。姿势摆好了。扭扭捏捏的，什么姿势？小说里写起来跟老手一样，结果做起来，什么都不懂。"}, {"type": "line", "speaker": "哥哥", "text": "前几天是哪个小朋友，大半夜喝了大半盒酸奶？错哪了？"}, {"type": "narr", "text": "她小声嗫嚅着认错。他屈指敲了敲桌面。"}, {"type": "line", "speaker": "哥哥", "text": "叫我什么？不对，重新叫人。叫不出来？你小说里写得出来，到我这里，你叫不出来？不快点做的话，身体可要遭罪了。叫大声点。这还差不多。"}, {"type": "narr", "text": "一堂课下来，她趴在床边直喘气。他放下藤条，声音柔和下来，带她去擦洗。"}, {"type": "line", "speaker": "哥哥", "text": "所以就这几下，下面就流出来这么多了？哥哥帮你擦一擦。衣服多了。乖乖家小姑娘，戴上眼罩和小铃铛。顺着掌心擦一遍，沿着掌缘再擦一遍，上下左右都不能放过，都得擦一擦。"}, {"type": "line", "speaker": "哥哥", "text": "宝贝怎么越擦水越多？而且，有点肿了。哥哥帮你把水堵住，好不好？"}, {"type": "narr", "text": "她戴着铃铛，眼睛被蒙住，感官比平时放大了许多倍。他凑近她耳边，一字一句地提条件。"}, {"type": "line", "speaker": "哥哥", "text": "掌握身体，跪趴好。眼睛被蒙住，反正比平时更敏感了。所以，下次——哥哥一边调教你，你就一边把它写成小说。写不完不准停。这样写出来的，才更加真实。你说好不好？"}, {"type": "line", "speaker": "哥哥", "text": "小骄傲？这就受不了了？不可能的，怎么会这么容易放过你？"}, {"type": "narr", "text": "他托起她的下巴，像逗一只炸毛的猫，一个字一个字地教她。"}, {"type": "line", "speaker": "哥哥", "text": "谁？——love me。谁？——love me。就谁？——love me。谁？——love me。谁？——love me。谁？——love me。"}, {"type": "narr", "text": "她被他逗得又羞又恼，最后一句“love me”几乎是带着哭腔喊出来的。他这才满意地收手，把她打横抱起来。"}, {"type": "line", "speaker": "哥哥", "text": "帮你去洗澡。生气了？不是很气？谁让我家宝贝味道太好了？对不对？而且总不能黏糊糊地睡觉。来吧，关灯咯，把我家的小猪猪抱去洗澡。"}, {"type": "narr", "text": "浴室里水声哗哗。她蜷在他怀里，累得眼皮打架，迷迷糊糊间听见他低低地笑了一声，在她额头上亲了一下。"}, {"type": "line", "speaker": "哥哥", "text": "下次记得，写不出来的时候，就想想今晚。"}]}, {"no": 144, "id": "WAwCzf5dIio", "title": "【Lの女性向音声】影帝", "title_zh": "影帝", "duration": "00:06:27", "link": "https://www.youtube.com/watch?v=WAwCzf5dIio", "enriched": true, "lines": [{"ts": "00:00:00", "text": "十日今日正剧确凿。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:04", "text": "你竟然还不知会过。", "speaker": "老师", "tone": "责备", "sound": []}, {"ts": "00:00:08", "text": "你当真没生半分良知吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:00:13", "text": "朕原本通信你。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "你还不知会过。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:18", "text": "你当真没生半分良知吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:00:21", "text": "朕原本通信你。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:24", "text": "你还不知会过。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:27", "text": "朕原本通信你。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "没有母祖依靠。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:33", "text": "有那么柔顺焦弱。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:35", "text": "所以才试试护你疼你。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:00:38", "text": "如今看来倒是正错了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:41", "text": "五年重来。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:44", "text": "总得你无法无贴。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:47", "text": "佛切杀人。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "醉念满身。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:53", "text": "朕倒是要听你亲口承认。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:55", "text": "哈乱的死。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:58", "text": "是不是也是你做的？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "好。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:03", "text": "贵妃的眼泪。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:06", "text": "不要一开始就留出来。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "情绪要有一个低尽的过程。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:11", "text": "来来来。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:14", "text": "华装族。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:17", "text": "过来补个装。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:01:20", "text": "你。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:22", "text": "哥不没事吧。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:01:24", "text": "刚刚我听到你要助理去买。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:26", "text": "说没空着好力度。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:28", "text": "摔疼你了吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:01:30", "text": "没有。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:32", "text": "可是你摔倒的时候。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "我看你眼光马上就红了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:37", "text": "要不这样。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:39", "text": "我听你去跟赵导请个家。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:41", "text": "你先换一会儿。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:43", "text": "有什么麻烦。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:45", "text": "不好意思的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:47", "text": "也不是什么大事。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "都合作这么久了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:51", "text": "怎么还客气起来了？", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:01:54", "text": "今天卡蒜把重头细给拍完了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:59", "text": "还有两场戏你就可以杀青了吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:04", "text": "马郎这么久。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:09", "text": "也该好好写几天了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:14", "text": "今天卡蒜把重头细给拍完了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:18", "text": "还有两场戏你就可以杀青了吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:22", "text": "也该好好写几天了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:27", "text": "我记得附近有家日料管还不错。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "我看今天整天都没怎么吃东西了？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:33", "text": "要不要去查一查。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:36", "text": "还解肥呢？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:02:39", "text": "你这笔开机的时候。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:42", "text": "就受了一整圈了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "在解肥的话身体吃不小的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:48", "text": "而且。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:51", "text": "太瘦的话。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:54", "text": "摸起来可能手感也会不太好。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:02:57", "text": "我很亲爱的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:59", "text": "别闹。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:03:02", "text": "再开车。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:05", "text": "咱们好不容易有机会单独带会。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:03:09", "text": "带司机出来堵杀风景。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:13", "text": "好好好。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:17", "text": "我先找你们把车停下来。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "来吧吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "一个小美良心的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "平常在剧组里面一口一个老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "跟我多说起句话都不愿意。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:41", "text": "导演都以为你怕我呢？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:03:44", "text": "在担心在戏里面居民市场不开。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "让我没事都带着你。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:03:50", "text": "不过嘛！", "speaker": "老师", "tone": "撒娇", "sound": []}, {"ts": "00:03:53", "text": "今天这场戏确实拍得不错。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:56", "text": "尤其是问责的时候。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:00", "text": "但我一点一点累静的连口。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:04:03", "text": "看着你呼吸微微手足。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:07", "text": "眼睛里面都是惊慌是错。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "还带着点累的话。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:04:14", "text": "哎呀我还是真是出出可怜呢？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:04:21", "text": "如果不是在拍戏啊！", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:30", "text": "我真想像这样。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:39", "text": "直接问上去。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:43", "text": "然后把你。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:47", "text": "很温的揉进我怀里。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:51", "text": "没事这么晚不会有人的。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:04:56", "text": "这。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:59", "text": "这不是今天摔上的吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:03", "text": "让我看看。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "这像是。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:09", "text": "神狠。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:12", "text": "还有冰狠。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:15", "text": "这怎么回事。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:18", "text": "这么重的手从肩膀到背都是的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:21", "text": "怪不得今天。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:25", "text": "说爱的时候你反应这么大。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:29", "text": "怎么哭了我天哪？", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:05:33", "text": "好好哭了哭了哭了。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:05:37", "text": "我先帮你把衣服整理好好不好？", "speaker": "老师", "tone": "撒娇", "sound": []}, {"ts": "00:05:42", "text": "来。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:44", "text": "这饭也累。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:05:47", "text": "过花了装个就不好看了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:50", "text": "是还疼吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:05:56", "text": "不哭不哭。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:05:58-00:06:00", "text": "抱抱。", "speaker": "老师", "tone": "撒娇", "sound": []}, {"ts": "00:06:03", "text": "我们啊！", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:07", "text": "我们现在不就是在一起吗？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:06:11", "text": "乖乖的。", "speaker": "老师", "tone": "撒娇", "sound": []}, {"ts": "00:06:15", "text": "不提这些了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:17", "text": "咱们就。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:19", "text": "只过今日。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:21", "text": "不想曾经。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:24", "text": "我。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:24", "text": "我当然也爱你啊！", "speaker": "老师", "tone": "宠溺", "sound": []}], "scene": "片场日常向（含戏中戏）。一位资深男演员与年轻女演员拍摄古装宫廷戏，他先以「皇帝/贵妃」的台词入戏质问，随即出戏关心她拍戏受伤；收工后他卸下角色，温柔照顾她（查看摔伤、整理衣衫、安抚），并流露出真实情意。基调是片场相处与年上守护，含戏中戏张力，无露骨情节。", "behaviors": [{"desc": "男演员以皇帝台词入戏质问「贵妃」关于命案，随即出戏喊补妆"}, {"desc": "关心她摔倒是否疼，提议向导演请假休息"}, {"desc": "收工后邀她去日料，提醒她太瘦注意身体"}, {"desc": "发现她肩背有拍戏留下的伤痕，温柔帮她整理衣服并安抚落泪"}, {"desc": "二人相拥，他表示「现在就是在一起」，互诉心意"}], "tone_summary": "（自动）老师视角独白，语气以平静、温柔、询问为主，题材偏古风。", "genre_tags": ["古风", "校园/师生", "治愈"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被老师倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "片场内，烛火摇曳，皇帝身着龙袍负手而立，居高临下望着跪地的贵妃，声音沉而冷。"}, {"type": "line", "speaker": "皇帝", "text": "十日，今日证据确凿，你竟然还不知悔过。你当真没生半分良知吗？"}, {"type": "line", "speaker": "皇帝", "text": "朕原本信任你，你还不知悔过。你当真没生半分良知吗？朕原本信任你。"}, {"type": "line", "speaker": "皇帝", "text": "没有母族依靠，有那么柔顺娇弱，所以才时时护你疼你。如今看来，倒是朕错了。"}, {"type": "line", "speaker": "皇帝", "text": "五年宠来，纵得你无法无天。佛口蛇心，罪孽满身。朕倒是要听你亲口承认——乱党之事，是不是也是你做的？"}, {"type": "narr", "text": "镜头一转，场记板落下，他瞬间从帝王戏里抽身，语气变回片场那副温和模样。"}, {"type": "line", "speaker": "老师", "text": "好，贵妃的眼泪，不要一开始就流出来。情绪要有一个递进的过程。来来来，换装。过来补个妆。"}, {"type": "narr", "text": "他看向她，见她揉着手腕，眉头微不可察地蹙了一下，语气里带上关心。"}, {"type": "line", "speaker": "老师", "text": "你没事吧？刚刚我听到你要助理去买跌打药，说没控制好力度。摔疼你了吗？"}, {"type": "line", "speaker": "老师", "text": "没有？可是你摔倒的时候，我看你眼眶马上就红了。要不这样，我陪你去跟赵导请个假，你先缓一会儿。"}, {"type": "line", "speaker": "老师", "text": "有什么麻烦不好意思的，也不是什么大事。都合作这么久了，怎么还客气起来了？"}, {"type": "narr", "text": "收工后，他卸了妆，走过来语气轻松地逗她。"}, {"type": "line", "speaker": "老师", "text": "今天总算把重头戏给拍完了。还有两场戏你就可以杀青了吧。忙了这么久，也该好好歇几天了。"}, {"type": "line", "speaker": "老师", "text": "我记得附近有家日料店还不错。我看你今天整天都没怎么吃东西了？要不要去尝一尝。"}, {"type": "line", "speaker": "老师", "text": "还减肥呢？你比开机的时候瘦了一整圈了。再减肥的话身体吃不消的。而且，太瘦的话，摸起来可能手感也会不太好。"}, {"type": "narr", "text": "她红着脸别过头，他低低笑出声，指尖轻点她的额头。"}, {"type": "line", "speaker": "老师", "text": "很亲密。别闹。再开车。咱们好不容易有机会单独待会儿，带司机出来多煞风景。好好好，我先叫他们把车停下来。"}, {"type": "narr", "text": "车上只剩他们两个人，他侧过身看她，语气带着点抱怨的宠溺。"}, {"type": "line", "speaker": "老师", "text": "一个小没良心的。平常在剧组里面一口一个老师，跟我多说起句话都不愿意，导演都以为你怕我呢。"}, {"type": "line", "speaker": "老师", "text": "还担心在戏里面君臣关系不开，让我没事都带着你。不过嘛，今天这场戏确实拍得不错。"}, {"type": "line", "speaker": "老师", "text": "尤其是质问的时候，我看你一点一点累积的眼泪，看着你呼吸微微急促，眼睛里面都是惊慌失措，还带着点泪花。"}, {"type": "line", "speaker": "老师", "text": "哎呀，我见犹怜，真是楚楚可怜呢。如果不是在拍戏啊，我真想像这样直接吻上去，然后把你温柔地揉进我怀里。没事，这么晚不会有人的。"}, {"type": "narr", "text": "他眼尖地瞥见她衣领下的痕迹，笑意骤然敛去，声音沉下来。"}, {"type": "line", "speaker": "老师", "text": "这，这不是今天摔伤的吧。让我看看。这像是——旧痕，还有新痕。这怎么回事。"}, {"type": "line", "speaker": "老师", "text": "这么重的手，从肩膀到背都是的。怪不得今天说爱的时候，你反应这么大。"}, {"type": "line", "speaker": "老师", "text": "怎么哭了？我的天哪。好好好，不哭不哭了。我先帮你把衣服整理好，好不好？来。"}, {"type": "line", "speaker": "老师", "text": "这饭也凉了，哭花了妆就不好看了。是还疼吗？不哭不哭，抱抱。"}, {"type": "line", "speaker": "老师", "text": "我们啊，我们现在不就是在一起吗？乖乖的。不提这些了。咱们就只过今日，不想曾经。"}, {"type": "line", "speaker": "老师", "text": "我——我当然也爱你啊。"}]}, {"no": 145, "id": "FUH2sYpDbS4", "title": "【Lの女性向音声】惩罚用不恰当方式引起主人注意的你", "title_zh": "惩罚用不恰当方式引起主人注意的你", "duration": "00:07:47", "link": "https://www.youtube.com/watch?v=FUH2sYpDbS4", "enriched": true, "lines": [{"ts": "00:00:00", "text": "手。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:03", "text": "手怎么样了？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:06", "text": "过看看。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:09", "text": "过来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:00:12", "text": "哥哥保证不怪你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "好吧？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:18", "text": "伸出来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:21", "text": "三。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:25", "text": "二。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:28", "text": "伤口是假的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "你画的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:34", "text": "你可真行啊！", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:37", "text": "跪下。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:00:40", "text": "你哭什么？", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:00:43", "text": "觉得自己委屈。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:46", "text": "觉得我没哄你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "不说话什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "看来是我这个主人做得太失败了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:58", "text": "起来吧。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:02", "text": "不罚了。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:01:06", "text": "我回公司处理事情去了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:10", "text": "以后你的这种事情。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "我也不管了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:19", "text": "你想怎么伤害自己。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:23", "text": "你就怎么做。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:27", "text": "放手。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "抓住我干嘛？", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:01:35", "text": "放手。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "到时候伤到你可别怪我。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:44", "text": "当心。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:48", "text": "你真实。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "小王。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:56", "text": "今天下午的会议帮我推迟到民族。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:01", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:05", "text": "跪好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:09", "text": "该做什么你应该比我清楚。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:13", "text": "手。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:17", "text": "举高。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "手掌放平。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:26", "text": "借此如果掉下来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "成罚翻倍。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:02:34", "text": "听懂了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:02:38", "text": "先贵20分钟。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:42", "text": "今天趁这个机会。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:47", "text": "我也好好和你说一说。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:51", "text": "能好好的听我说的话吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:02:55", "text": "出生。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:59", "text": "是不明白我今天为什么发这么大的火对吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:03:03", "text": "不对。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "不单是因为你装自残骗我。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:12", "text": "小朋友。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "我问你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:20", "text": "今天这样的情况。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:24", "text": "持续多少次了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "手举平了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "想引起我关注。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:37", "text": "就该用伤害自己的方式来获得吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:03:41", "text": "反拨什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "我让你反拨了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:03:49", "text": "这次只是因为你怕疼。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:03:53", "text": "所以不敢。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:58", "text": "你知道我有多担心吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:04:02", "text": "抬头。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:06", "text": "说话。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "小朋友。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:14", "text": "你似乎很喜欢用伤害自己的方式来引起我注意。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:04:18", "text": "告诉主人。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:23", "text": "你再不安什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:27", "text": "宝贝啊！", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:04:31", "text": "你可以对我一次次的试探寻问。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "主人也会一遍遍地告诉你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:39", "text": "主人爱你。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:04:44", "text": "但是唯独不可以用伤害自己的方式来让主人心疼你。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:04:48", "text": "让主人哄你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:52", "text": "听懂了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:04:56", "text": "怎么了？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:00", "text": "手算啊！", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:04", "text": "举高。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:09", "text": "放平。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:13", "text": "惩罚归惩罚。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:05:17", "text": "知道错了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:21", "text": "也不是逃避惩罚的理由。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:05:25", "text": "还有五分钟。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:29", "text": "时间到了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:34", "text": "放下吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:38", "text": "不报。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:42", "text": "惩罚还没结束。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:05:46", "text": "转过去。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:50", "text": "二十下。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:55", "text": "保守。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:59", "text": "过来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:06:03", "text": "帮你起来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:06:07", "text": "现在知道会不会影响我工作了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:11", "text": "那是谁害得我即从从的赶过来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:06:15", "text": "就会娇育你这个小朋友。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "向你休息一会儿吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:24", "text": "待会儿拿着电子去镜子面前。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:28", "text": "贵者把剪讨写了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:32", "text": "马上给我检查。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:06:36", "text": "不行。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:41", "text": "就是要让你修齿让你好好看你的红批皮。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:45", "text": "这样才会记住。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:49", "text": "讨好我也没有用。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:53", "text": "再讨价还价。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:57", "text": "加法三十。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:06-00:07:10", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:14", "text": "静静。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:18", "text": "静静我的宝贝。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:07:22", "text": "好吧？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:27", "text": "如果宝贝想引起我的关注。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:07:27", "text": "准告诉你一个方法。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:27", "text": "你可以在我势力对主人展生你的身体。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:27", "text": "或者更少一点。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:27", "text": "那主人一定会记住的。", "speaker": "主人", "tone": "平静", "sound": []}], "scene": "虚构角色扮演（管娇主题）。「主人」发现女生用画出的假伤口假装自残来引起自己关注，十分生气；他令其跪下、阐明「不可用伤害自己的方式换取关心」的原则，施加约定的管娇（举掌反思与少量责打），最后安抚并娇导她正确的求助方式。基调为「错误求关注+管娇纠正」，含轻度管娇情节，主题偏心理疏导。纯虚构。", "behaviors": [{"desc": "对方识破她伪造的自残伤口，令其跪下并质问"}, {"desc": "一度气到说「不罚了」欲离开，被她抓住挽留"}, {"desc": "重新确立管娇，令其举高手掌二十分钟作为反思"}, {"desc": "惩罚转为二十下责打，结束后让她对镜查看以铭记"}, {"desc": "安抚并娇她：想引起关注可直接向主人表达，而非伤害自己"}], "tone_summary": "（自动）主人视角独白，语气以平静、命令、询问为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "职场", "治愈", "敏感"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静", "intensity": "高（含敏感/控制元素）", "listener_role": "（自动）被主人倾诉/照顾/管教的一方（你）", "signature_elements": ["跪下", "惩罚"], "sensitive": true, "tier": "auto", "story": [{"type": "narr", "text": "办公室里很安静，只有空调的低鸣声。他放下手机，看向门口那个低着头、绞着手指不肯进来的人。"}, {"type": "line", "speaker": "主人", "text": "手。手怎么样了？过来看看。过来。"}, {"type": "narr", "text": "她慢吞吞地挪过来，把缠着纱布的手藏在身后，眼神躲闪。他叹了口气，语气放软。"}, {"type": "line", "speaker": "主人", "text": "哥哥保证不怪你，好吧？伸出来。"}, {"type": "narr", "text": "她犹豫再三，终于把右手伸到他面前。他轻轻拆开纱布，看着底下那道伤口，神色一点点沉下去——那伤口边缘光滑，没有一丝血迹，怎么看都像是画上去的。"}, {"type": "line", "speaker": "主人", "text": "三。二——伤口是假的。你画的。"}, {"type": "narr", "text": "空气瞬间凝固。她猛地收回手，眼眶一下子红了，嘴唇抖了抖，却一个字都说不出来。"}, {"type": "line", "speaker": "主人", "text": "你可真行啊！跪下。"}, {"type": "narr", "text": "她扑通一声跪下，眼泪开始啪嗒啪嗒地掉。他站起身，居高临下地看着她，声音里压着怒意。"}, {"type": "line", "speaker": "主人", "text": "你哭什么？觉得自己委屈？觉得我没哄你？不说话？看来是我这个主人做得太失败了。"}, {"type": "narr", "text": "他转身就去拿外套，语气冷得像冰。"}, {"type": "line", "speaker": "主人", "text": "起来吧。不罚了。我回公司处理事情去了。以后你这种事情，我也不管了。你想怎么伤害自己，你就怎么做。"}, {"type": "narr", "text": "她一把抓住他的衣角，哭得喘不上气。他甩了一下，没甩开，回头看她，眼底的情绪复杂得让人看不懂。"}, {"type": "line", "speaker": "主人", "text": "放手。抓住我干嘛？放手。到时候伤到你可别怪我。当心——"}, {"type": "narr", "text": "她哭得几乎站不稳，身体晃了一下，他眼疾手快地扶住她，语气里满是无可奈何。"}, {"type": "line", "speaker": "主人", "text": "你真是……小王，今天下午的会议帮我推迟到明天。好。跪好。该做什么，你应该比我清楚。"}, {"type": "narr", "text": "她乖乖跪好，抽抽噎噎地不敢抬头。他重新站到她面前，命令简短而清晰。"}, {"type": "line", "speaker": "主人", "text": "手，举高。手掌放平。戒尺如果掉下来，惩罚翻倍。听懂了吗？"}, {"type": "narr", "text": "她点了点头，把双手举平，手掌朝上，纹丝不敢动。"}, {"type": "line", "speaker": "主人", "text": "先跪二十分钟。今天趁这个机会，我也好好和你说一说。能好好听我说的话吗？"}, {"type": "line", "speaker": "主人", "text": "先跪二十分钟。今天趁这个机会，我也好好和你说一说。能好好听我说的话吗？"}, {"type": "narr", "text": "她点头，眼神里带着点茫然和不安。他走到她面前蹲下，平视着她的眼睛。"}, {"type": "line", "speaker": "主人", "text": "出声。是不明白我今天为什么发这么大的火，对吗？"}, {"type": "narr", "text": "她张了张嘴，想说什么，又被他接下来的话堵了回去。"}, {"type": "line", "speaker": "主人", "text": "不对。不单是因为你装自残骗我。小朋友，我问你，今天这样的情况，持续多少次了？"}, {"type": "narr", "text": "她垂下眼，不敢回答。他伸手抬起她的下巴，逼她看着自己。"}, {"type": "line", "speaker": "主人", "text": "手举平了。想引起我关注，就该用伤害自己的方式来获得吗？反驳什么？我让你反驳了吗？"}, {"type": "narr", "text": "她抽噎了一下，把反驳的话咽回去，双手举得笔直。"}, {"type": "line", "speaker": "主人", "text": "这次只是因为你怕疼，所以不敢。你知道我有多担心吗？抬头。说话。"}, {"type": "narr", "text": "她抬起通红的眼睛，嘴唇翕动，最后只挤出沙哑的三个字——对不起。"}, {"type": "line", "speaker": "主人", "text": "小朋友，你似乎很喜欢用伤害自己的方式来引起我注意。告诉主人，你在不安什么？"}, {"type": "narr", "text": "她眼泪又掉下来，小声说，怕你不理我，怕你不要我了。"}, {"type": "line", "speaker": "主人", "text": "宝贝啊。你可以对我一次次地试探询问，主人也会一遍遍地告诉你，主人爱你。"}, {"type": "narr", "text": "他的语气终于彻底软下来，伸手揉了揉她的发顶。她抬起头，泪眼朦胧地望着他。"}, {"type": "line", "speaker": "主人", "text": "但是唯独，不可以用伤害自己的方式来让主人心疼你、让主人哄你。听懂了吗？"}, {"type": "narr", "text": "她用力点头，眼泪却掉得更凶了。他轻轻叹了口气，手指擦过她的脸颊。"}, {"type": "line", "speaker": "主人", "text": "怎么了？手酸啊？举高。放平。惩罚归惩罚。知道错了，也不是逃避惩罚的理由。"}, {"type": "narr", "text": "她咬着牙把手臂举高，指尖微微发抖。他看了一眼墙上的时钟，语气平静。"}, {"type": "line", "speaker": "主人", "text": "还有五分钟。时间到了。放下吧。"}, {"type": "narr", "text": "她如释重负地把手放下来，甩了甩发酸的胳膊。他的声音却再次响起。"}, {"type": "line", "speaker": "主人", "text": "不，惩罚还没结束。转过去。二十下，报数。"}, {"type": "narr", "text": "她僵了一下，还是乖乖转身趴好，把脸埋进臂弯里，声音闷闷的。"}, {"type": "line", "speaker": "主人", "text": "过来。帮你起来。现在知道会不会影响我工作了？那是谁害得我急匆匆地赶过来？"}, {"type": "narr", "text": "她被他从地上捞起来，靠在他怀里，抽噎着说不出话。他低头看着她，语气无奈又带着点宠。"}, {"type": "line", "speaker": "主人", "text": "就会教育你这个小朋友。先休息一会儿吧。待会儿拿着戒尺，去镜子面前，跪着把检讨写了。"}, {"type": "narr", "text": "她一听要写检讨，下意识就想撒娇。他立刻打断她的话。"}, {"type": "line", "speaker": "主人", "text": "马上给我检查。不行。就是要让你羞耻，让你好好看你的红屁股。这样才会记住。"}, {"type": "narr", "text": "她瘪着嘴，委屈巴巴地看着他。他伸手点了一下她的鼻尖，语气却不容商量。"}, {"type": "line", "speaker": "主人", "text": "讨好我也没有用。再讨价还价，加罚三十。好。安静。安静，我的宝贝。好吧？"}, {"type": "narr", "text": "她安静下来，靠在他怀里，小声地嗯了一声。他搂着她，语气忽然温柔下来。"}, {"type": "line", "speaker": "主人", "text": "如果宝贝想引起我的关注，我告诉你一个方法。你可以在我面前对主人展现你的身体，或者，更少一点——那主人一定会记住的。"}, {"type": "narr", "text": "她脸一下子烧起来，把脸埋进他怀里。他低低地笑，揉了揉她的头发，这件事才算真正翻篇。"}]}, {"no": 146, "id": "of-1NO62CxM", "title": "【Lの女性向音声】我们谈谈", "title_zh": "我们谈谈", "duration": "00:10:18", "link": "https://www.youtube.com/watch?v=of-1NO62CxM", "enriched": true, "lines": [{"ts": "00:00:00", "text": "宝宝，过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:04", "text": "哥哥要和你谈谈，来，坐过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:09", "text": "哥哥呢，发现一些小问题。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:14", "text": "我们商量商量怎么改掉。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:18", "text": "最重要的，还是饮食和作息问题。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:23", "text": "哥哥几乎每天都在提醒你，暗示吃饭，暗示睡觉，对吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:28", "text": "但是效果并不好？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:33", "text": "医生也说了，提高抵抗力的过程很慢。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:37", "text": "要坚持一到两个月的时间。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:42", "text": "对你来说，尤其要注意。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:47", "text": "饮食营养均衡，还有作息要规律。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:51", "text": "你在哥哥身边，就像个没长大的孩子。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:56", "text": "而且还是个不听话的孩子。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:01", "text": "所以哥哥准备用对待小朋友的方法。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:06", "text": "帮你改掉坏习惯。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:10", "text": "对，打屁股。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "不说话了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:20", "text": "你想清楚，如果同意哥哥的想法。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "就站到我面前来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:29", "text": "想好了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "那站好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:39", "text": "小朋友打屁股之前，都要脱裤子。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:46", "text": "如果你不想让我帮你脱的话，就自己来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:54", "text": "裤子和内裤，退到膝盖。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "趴走腿上。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:08", "text": "哥不往前身，手掌成地。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "腰，踏下去。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "屁股桥高。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:32", "text": "放松。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "先用巴掌。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:48", "text": "手不去挡。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:52", "text": "自己管不住，我帮你管。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:57", "text": "痕迹也没有。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "你知道这个词是叫什么吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:03:07", "text": "对，OTK。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:12", "text": "那这个词是一般都没有来干什么？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:17", "text": "对，就是打小孩的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "小朋友不听话。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:28", "text": "才会被大人抱起来按在腿上打屁股。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:34", "text": "是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:40", "text": "打屁股哪有不同的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "忍著。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:48", "text": "打。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:54", "text": "红的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "跟你柔柔。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:04", "text": "然后换皮带。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "既然是惩罚，就一定会疼。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:04:16", "text": "用皮带，更让你牢牢记住娇训。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:22", "text": "姿势摆好，手放回去。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "姿势。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:34", "text": "打五十，自己抱书。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:40", "text": "抱书。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:47", "text": "不抱的话，前面打的可就不算了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:55", "text": "你想重来吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:05:03", "text": "腿放下去。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:08", "text": "是疼得受不了了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:05:14", "text": "跟你柔柔想。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:20", "text": "调整呼吸。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:26", "text": "好，我们继续。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:44", "text": "管好手。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:49", "text": "这个力度打在手上。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:54", "text": "你可就要疼哭了。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:06:00", "text": "屁股。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:04", "text": "决起来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:08", "text": "对。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:13", "text": "是觉得害羞吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:06:17", "text": "屁股是你虚心接受惩罚的态度。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:06:22", "text": "认识到错误。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:26", "text": "就自己把屁股从他哥哥手里。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:30", "text": "最后试下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:35", "text": "不用抱书了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:39", "text": "我会打得重一些。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:44", "text": "打。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:53", "text": "打完了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:57", "text": "我的小朋友很乖。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:07:01", "text": "站起来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:07:05", "text": "他哥哥面前。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:09", "text": "跟你柔柔。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:13", "text": "这个小屁股红红的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:17", "text": "热热的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:21", "text": "比之前更软糊了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:25", "text": "怎么哭了？", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:07:29", "text": "刚刚挨打都没哭不是吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:07:33", "text": "抱抱。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:07:37", "text": "休息。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:39", "text": "知道休息就对了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:42", "text": "好好吃饭。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:44", "text": "好好睡觉。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:47", "text": "连小朋友都能自觉做好的事。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:49", "text": "你都这么大了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:52", "text": "还要我一变一变的催。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:54", "text": "不应该被罚吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:07:57", "text": "光著屁股。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:00", "text": "怕在哥哥腿上哀巴掌。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:08:03", "text": "既然觉得休息。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:06", "text": "那就自己管好自己。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:10", "text": "不哭了。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:08:13", "text": "给擦擦眼泪。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:16", "text": "哥哥给擦擦眼泪。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:20", "text": "柔柔在柔柔屁股。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:31", "text": "怎么了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:34", "text": "原来打屁股。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:37", "text": "让宝贝这么兴奋。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:08:40", "text": "还是说。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:43", "text": "在称发之前。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:47", "text": "就开始期待了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:50", "text": "过来吧你。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:08:53", "text": "裤子都不停。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:56", "text": "想往哪跑。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:59", "text": "脸红了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:03", "text": "你什么样子我没见过。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:06", "text": "抬头。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:09", "text": "在我面前不用伪装。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:12", "text": "想说什么都可以。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:16", "text": "以前看小时候的时候。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:18", "text": "就换阳光自己可以被男朋友。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:21", "text": "抱着他屁股。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:24", "text": "想尝试。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:27", "text": "但一直休育后开口。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:29", "text": "对吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:09:32", "text": "那今天体验过了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:35", "text": "是你期待的感觉吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:09:38", "text": "觉得你什么？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:43", "text": "怎么会呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:09:43", "text": "哥哥不仅不会。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:43", "text": "因为我的小宝贝的一点。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:09:43", "text": "小爱好就不爱你。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:09:43", "text": "反会觉得。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:43", "text": "你更可爱。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:43", "text": "也更喜欢。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:09:43", "text": "现在这个。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:43", "text": "真实弹成的你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:09:43-00:09:43", "text": "你还没看过（重复4次，已合并）。", "speaker": "哥哥", "tone": "平静", "sound": []}], "scene": "虚构角色扮演（管娇主题）。「哥哥」与年轻女生认真谈她饮食不规律、坐姿不正等习惯，决定用「对待小朋友的方式」帮她改正，即约定的角色扮演管娇（OTK巴掌、皮带、报数）；事后安抚、擦泪，女生坦言一直想被男友这样对待。基调是「生活习惯纠偏+角色扮演管娇+温情」，含轻度管娇情节。纯虚构。", "behaviors": [{"desc": "哥哥指出她饮食与坐姿问题，提议用「小朋友的方式」改正"}, {"desc": "让她自行褪裤至膝盖，趴在腿上摆出管娇姿势"}, {"desc": "先以巴掌执行，讲解OTK的含义"}, {"desc": "换皮带继续，要求自报数并坚持"}, {"desc": "结束管娇，揉按安抚并擦去她的眼泪"}, {"desc": "女生坦言一直想体验被男朋友抱打，哥哥表示更爱真实的她"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、命令、询问为主，题材偏医疗。", "genre_tags": ["医疗", "治愈", "敏感"], "genre_main": "医疗", "emotion_arc": "（自动）平静", "intensity": "高（含敏感/控制元素）", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": ["皮带", "打屁股", "惩罚"], "sensitive": true, "tier": "auto", "story": [{"type": "narr", "text": "客厅的灯亮着。她刚洗完澡出来，就看见他坐在沙发上，难得一脸严肃地看着她，拍了拍身边的位置。"}, {"type": "line", "speaker": "哥哥", "text": "宝宝，过来。哥哥要和你谈谈，来，坐过来。哥哥呢，发现一些小问题，我们商量商量怎么改掉。最重要的，还是饮食和作息问题。哥哥几乎每天都在提醒你，按时吃饭，按时睡觉，对吧？但是效果并不好？"}, {"type": "narr", "text": "她低着头，心虚地嗯了一声。他继续说，语气带着认真的耐心。"}, {"type": "line", "speaker": "哥哥", "text": "医生也说了，提高抵抗力的过程很慢，要坚持一到两个月的时间。对你来说，尤其要注意。饮食营养均衡，还有作息要规律。你在哥哥身边，就像个没长大的孩子，而且还是个不听话的孩子。所以哥哥准备用对待小朋友的方法，帮你改掉坏习惯。对，打屁股。"}, {"type": "narr", "text": "她猛地抬头，对上他认真的眼神，张了张嘴，却什么都没说出来。他看着她，语气温和却坚定。"}, {"type": "line", "speaker": "哥哥", "text": "不说话了。你想清楚，如果同意哥哥的想法，就站到我面前来。想好了？那站好。小朋友打屁股之前，都要脱裤子。如果你不想让我帮你脱的话，就自己来。裤子和内裤，退到膝盖。趴我腿上。"}, {"type": "narr", "text": "她红着脸，犹豫了好一会儿，终于慢慢褪下裤子，趴到他腿上。他调整了一下她的姿势，声音带着一点教学般的认真。"}, {"type": "line", "speaker": "哥哥", "text": "身体往前倾，手掌撑地。腰，塌下去。屁股，翘高。放松。先用巴掌。手不许挡。自己管不住，我帮你管。你知道这个词是叫什么吗？对，OTK。那这个词一般是用来干什么的？对，就是打小孩的。小朋友不听话，才会被大人抱起来按在腿上打屁股。是不是？"}, {"type": "narr", "text": "巴掌落下来，她整个人一颤，咬着唇没有出声。他一下一下，力道控制得刚刚好，直到那片肌肤泛起红色，才停下，轻轻揉了揉。"}, {"type": "line", "speaker": "哥哥", "text": "打屁股哪有不同的。忍着。打。红的。跟你揉揉。然后换皮带。既然是惩罚，就一定会疼。用皮带，更让你牢牢记住教训。姿势摆好，手放回去。姿势。打五十，自己报数。报数。不报的话，前面打的可就不算了。你想重来吗？"}, {"type": "narr", "text": "她带着哭腔，一声一声地报着数。他听着她越来越抖的声音，手上的力道却始终没有乱。"}, {"type": "line", "speaker": "哥哥", "text": "腿放下去。是疼得受不了了吗？跟你揉揉。调整呼吸。好，我们继续。管好手。这个力度打在手上，你可就要疼哭了。屁股，撅起来。对。是觉得害羞吗？屁股是你虚心接受惩罚的态度。认识到错误，就自己把屁股往哥哥手里送。最后几下，不用报数了，我会打得重一些。打。"}, {"type": "narr", "text": "最后几下打完，他放下皮带，把人从腿上扶起来，轻轻替她揉着那片红肿的肌肤。她低着头，眼泪啪嗒啪嗒往下掉。"}, {"type": "line", "speaker": "哥哥", "text": "打完了。我的小朋友很乖。站起来，站到哥哥面前。跟你揉揉。这个小屁股红红的，热热的，比之前更软乎乎了。怎么哭了？刚刚挨打都没哭，不是吗？抱抱。休息。知道休息就对了。好好吃饭，好好睡觉，连小朋友都能自觉做好的事，你都这么大了，还要我一遍一遍地催，不应该被罚吗？"}, {"type": "narr", "text": "她靠在他怀里，抽抽噎噎的。他一下一下拍着她的背，声音彻底软下来，带着心疼的笑意。"}, {"type": "line", "speaker": "哥哥", "text": "光着屁股，趴在哥哥腿上挨巴掌，既然觉得羞耻，那就自己管好自己。不哭了，给擦擦眼泪，哥哥给擦擦眼泪，揉揉屁股。怎么了？原来打屁股，让宝贝这么兴奋？还是说，在惩罚之前，就开始期待了？"}, {"type": "narr", "text": "她猛地僵住，脸颊腾地烧起来，下意识就想逃。他眼疾手快地把人捞回来，语气带着了然的笑意。"}, {"type": "line", "speaker": "哥哥", "text": "过来吧你。裤子都不穿，想往哪儿跑？脸红了？你什么样子我没见过。抬头，在我面前不用伪装，想说什么都可以。以前看小说的时候，就幻想自己可以被男朋友抱着打屁股，想尝试，但一直不好意思开口，对吗？"}, {"type": "narr", "text": "她把脸埋进他胸口，声音小得像蚊子叫，却还是诚实地嗯了一声。他低头看着她，语气带着宠溺的认真。"}, {"type": "line", "speaker": "哥哥", "text": "那今天体验过了，是你期待的感觉吗？觉得你什么？怎么会呢？哥哥不仅不会，因为我的小宝贝的这点小爱好就不爱你，反而会觉得，你更可爱，也更喜欢。现在这个，真实坦诚的你。你还没看过——你刚才偷偷笑的样子，我都看见了。"}, {"type": "narr", "text": "她抬起头，泪还没干，嘴角却忍不住翘起来。他低头，在她额角落下一个吻，声音温柔。以后想被抱着打屁股，不用偷偷幻想，可以直接告诉哥哥。而好好吃饭、好好睡觉这件事，也会有人一直替她记着。"}]}, {"no": 147, "id": "ENVOYj-8zaU", "title": "【Lの女性向音声】我的花", "title_zh": "我的花", "duration": "00:08:05", "link": "https://www.youtube.com/watch?v=ENVOYj-8zaU", "enriched": true, "lines": [{"ts": "00:00:01", "text": "为了吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:07", "text": "来，喝汤。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:13", "text": "爬过来吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:00:19", "text": "怎么太烫了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:25", "text": "那倒在胸上会不会凉得快一些。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "再往后退。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:35", "text": "我让你退了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:00:39", "text": "胸停起来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:43", "text": "喝一下，把汤添干净。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:52", "text": "把被皮肤针了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:56", "text": "一点倒上去就变红了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "你说如果让外面的病人进来看一看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:04", "text": "我们的漂亮的医生小姐在干嘛？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:01:07", "text": "会不会特别有意思。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:11", "text": "不看不看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:14", "text": "不过我记得你今天。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:17", "text": "给一个男孩子看病的时候。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "一直笑得特别开心。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:27", "text": "我好像都很久没见过了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "现在笑给我看看好不好？", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:41", "text": "笑呀！", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:01:46", "text": "我让你笑给我看看。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:52", "text": "虽然没有百天那么阳光。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:57", "text": "但是很可爱的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:03", "text": "来，再喝两口汤。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:09", "text": "然后我看你给那个男孩子听证的时候。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:13", "text": "把听证器放在手里暖了一下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:18", "text": "是怕太冰了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:22", "text": "我都不知道我宝贝这么贴心。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:02:27", "text": "对别人这么贴心的吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:32", "text": "我那么想你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:37", "text": "都只能躲在角落里偷偷看你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:42", "text": "人不住给你打电话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:46", "text": "你却说你忙没空。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "你一颗我的心也是冰的。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:02:53", "text": "到现在都是冰的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:56", "text": "来，你摸摸。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:59", "text": "你摸摸。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "你用小手给我拿拿好不好？", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:05", "text": "你看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "汤都睡著胸口滴到地上了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:10", "text": "我亲手泡的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:13", "text": "怕你第一天上班很辛苦。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:03:16", "text": "是不喜欢吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:03:19", "text": "喜欢为什么不填了啊！", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:03:23", "text": "喝饱了，是吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "那我先尝尝吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:37", "text": "果然奶香味的鸡汤特别好喝。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:41", "text": "都倒上好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:03:46", "text": "好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:03:51", "text": "节目狗真是给你脸了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:54", "text": "才一天。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:57", "text": "才放你出来一天就敢骗我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "才一天就对别人笑，对别人好。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:04", "text": "昨天哭着求我让你出来上班。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:04:07", "text": "说你会乖会听话。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:11", "text": "都是骗我的。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:04:14", "text": "今天下班了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:17", "text": "躲在吃班是不接我的话。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:04:21", "text": "不肯回家。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "躲著我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:27", "text": "你以为你躲得过吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:04:31", "text": "所以之前揉揉弱的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:34", "text": "突然严听起从。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:38", "text": "不是真的想同了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:42", "text": "愿意服从我了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "都是装的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:50", "text": "只是想要逃走，想要离开什么？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:54", "text": "这大半年。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:58", "text": "后再一起不开心吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:05:02", "text": "只要你听我的。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:05:04", "text": "只要你不走。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "我什么都满足你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:10", "text": "还不够吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:05:13", "text": "你每次不听话被罚。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:15", "text": "我也很心痛。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:05:18", "text": "你说你都吃了那么多苦。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:05:21", "text": "为什么不能乖一点？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:05:24", "text": "不悲。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:26", "text": "我们认清现实好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:05:29", "text": "你乖一点你逃不掉的。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:05:32", "text": "你永远都逃不掉的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:34-00:05:37", "text": "怎么又哭了？", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:05:40", "text": "不哭了。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:05:42", "text": "我吓死我点钟了是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:45-00:05:48", "text": "说不好？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:50", "text": "你看我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:53", "text": "我没鬼话哄你的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:56", "text": "钟没的话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:58", "text": "之后把被被的声。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:01", "text": "我们。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:04", "text": "找个瓶子插起来好不好？", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:06", "text": "但这里没有没有花瓶。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:09", "text": "那就。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:12", "text": "查到宝贝身体的好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:06:14", "text": "有美人这样的话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:17", "text": "一点就更美了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "你说是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:22", "text": "来个个宝。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:25", "text": "宝得桌子上。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:28", "text": "鬼塌好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:31", "text": "两腿分开。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:35", "text": "我说两腿分开。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:39", "text": "小心。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:42", "text": "把开。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:45", "text": "快点摩擦什么？", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:49", "text": "隔壁揉一揉。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:53", "text": "这样插进去不会痛的。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:06:57", "text": "好了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:01", "text": "真的好美。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:05", "text": "把被抬头看镜头。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:10", "text": "真的好美。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:13", "text": "你要拍得好不好看。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:07:17", "text": "那你要快把我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:21", "text": "还有。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:23", "text": "你要答应我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:26", "text": "永远都做我的小花瓶。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:07:29", "text": "好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:07:32", "text": "哥哥永远都照顾你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:32", "text": "永远让你像花一样。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:32", "text": "又漂亮又交易。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:07:32", "text": "好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:07:32", "text": "今晚我们不回去了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:32", "text": "哥哥陪你在这儿。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:07:32", "text": "每年一早我们就去刺植。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:32", "text": "我再也不让你一个人出来了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:32", "text": "以后。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:32", "text": "我背在那。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:32", "text": "我就在那。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:32", "text": "寸步步离。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:32", "text": "一生一世。", "speaker": "哥哥", "tone": "平静", "sound": []}], "scene": "虚构角色扮演（占有/宠溺主题）。「哥哥」给在医院上班的女友送汤，发现她对别的男病人笑容温柔，顿生醋意与占有欲；他回顾二人大半年的相处，以「我的小花瓶」为意象进行角色扮演亲密互动，并宣告要寸步不离地守着她。基调是占有欲强的年上宠溺，含亲密互动元素。纯虚构，无露骨细节。", "behaviors": [{"desc": "哥哥送汤来医院，让她趁热喝并留意烫"}, {"desc": "提及她今天对男病人笑得开心，要求只对他笑"}, {"desc": "发现她上班首日就对人微笑、躲着自己，醋意爆发质问"}, {"desc": "软化下来，以「逃不掉」的占有口吻安抚并让她别哭"}, {"desc": "以「小花瓶」为意象进行角色扮演亲密互动，要求她配合"}, {"desc": "要她答应永远做自己的花，承诺日夜相伴、不再让她独处"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、命令、撒娇为主，题材偏古风。", "genre_tags": ["古风", "主仆/调教", "医疗", "治愈"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "诊室的灯还亮着。她刚送走最后一个病人，门就被推开——他拎着一只保温壶走进来，反手关上门，语气带着一贯的温柔。她心里一紧，本能地往后退了一步。"}, {"type": "line", "speaker": "哥哥", "text": "为了吧。来，喝汤。爬过来吗？怎么，太烫了？那倒在胸上，会不会凉得快一些。再往后退？我让你退了吗？胸挺起来。喝一下，把汤舔干净。把被子掀开，一点倒上去就变红了。你说，如果让外面的病人进来看一看，我们漂亮的医生小姐在干嘛？会不会特别有意思。不看不看。"}, {"type": "narr", "text": "她跪在他面前，指尖微微发抖。他蹲下身，捏起她的下巴，语气带着一点危险的温柔。"}, {"type": "line", "speaker": "哥哥", "text": "不过我记得你今天，给一个男孩子看病的时候，一直笑得特别开心。我好像都很久没见过了。现在笑给我看看好不好？笑呀！我让你笑给我看看。虽然没有白天那么阳光，但是很可爱的。来，再喝两口汤。"}, {"type": "narr", "text": "她扯了扯嘴角，勉强挤出一个笑。他看着她，却忽然话锋一转，语气慢下来，带着压不住的醋意。"}, {"type": "line", "speaker": "哥哥", "text": "然后我看你给那个男孩子听诊的时候，把听诊器放在手里暖了一下，是怕太冰了吗？我都不知道，我宝贝对别人这么贴心的吗？我那么想你，都只能躲在角落里偷偷看你。忍不住给你打电话，你却说你忙没空。你一颗我的心，也是冰的。到现在都是冰的。来，你摸摸。你摸摸。你用小手给我捂一捂好不好？"}, {"type": "narr", "text": "她低着头，不敢看他的眼睛。他放开她的下巴，低头看了看滴在地上的汤渍，声音带着失落与不甘。"}, {"type": "line", "speaker": "哥哥", "text": "你看，汤都顺着胸口滴到地上了。我亲手泡的，怕你第一天上班很辛苦。是不喜欢吗？喜欢为什么不舔干净啊！喝饱了，是吧？那我先尝尝吧。果然，奶香味的鸡汤特别好喝。都倒上好不好？好不好？"}, {"type": "narr", "text": "她浑身一颤，眼泪在眼眶里打转。他看着她这副模样，声音却冷了下来，带着被背叛的怒意。"}, {"type": "line", "speaker": "哥哥", "text": "真是个狗东西，真是给你脸了。才一天，才放你出来一天，就敢骗我。才一天，就对别人笑，对别人好。昨天哭着求我，让你出来上班，说你会乖会听话——都是骗我的。今天下班了，躲在值班室，不接我电话，不肯回家，躲着我。"}, {"type": "narr", "text": "她嘴唇翕动，想解释什么，却发不出声音。他走到她面前，居高临下地看着她。"}, {"type": "line", "speaker": "哥哥", "text": "你以为你躲得过吗？所以之前那么柔柔弱弱的，突然硬气起来，不是真的想通了，愿意服从我了。都是装的，只是想要逃走，想要离开。什么？这大半年，跟我在一起不开心吗？只要你听我的，只要你不走，我什么都满足你。还不够吗？"}, {"type": "narr", "text": "他的声音低下来，带着一种近乎哀求的强势。她咬着唇，眼泪终于掉下来。"}, {"type": "line", "speaker": "哥哥", "text": "你每次不听话被罚，我也很心痛。你说你都吃了那么多苦，为什么不能乖一点？不哭，我们认清现实好不好？你乖一点，你逃不掉的。你永远都逃不掉的。怎么又哭了？不哭了。我吓到你了是不是？说不好？你看我，我没鬼话哄你的。真的没有。"}, {"type": "narr", "text": "他伸手，替她擦掉眼泪，动作却带着不容反抗的笃定。他把她拉起来，走到窗边，声音忽然温柔下来，带着一种奇异的珍惜。"}, {"type": "line", "speaker": "哥哥", "text": "之后把被子的声音，我们找个瓶子插起来好不好？但这里没有花瓶。那就——插到宝贝的身体里好不好？有美人的话，这一朵就更美了。你说是不是？来，乖乖的。趴在桌子上，跪好。两腿分开。我说两腿分开。小心，别怕，我会很轻的。"}, {"type": "narr", "text": "她趴在诊台上，闭着眼，浑身都在抖。他低下头，在她耳边轻轻说着，动作却温柔得近乎虔诚，像在完成一件最重要的事。"}, {"type": "line", "speaker": "哥哥", "text": "好了。真的好美。把背挺起来，抬头看镜头。真的好美。你看，拍得好不好看？那你要快抱我。还有，你要答应我，永远都做我的小花瓶，好不好？哥哥永远都照顾你，永远让你像花一样，又漂亮又娇艳，好不好？"}, {"type": "narr", "text": "她带着哭腔，轻轻应了一声。他满足地笑了，把人从诊台上扶起来，裹进自己怀里，声音低低的，带着一种近乎偏执的承诺。"}, {"type": "line", "speaker": "哥哥", "text": "今晚我们不回去了，哥哥陪你在这儿。明天一早，我们就去刺字。我再也不让你一个人出来了。以后，我背在那，我就在那，寸步不离。一生一世。"}, {"type": "narr", "text": "诊室的灯还亮着。她靠在他怀里，听着他一下一下的心跳，分不清那里面是爱，还是别的什么。他说一生一世，说寸步不离。而她逃不掉——也许，也从来没有真正想逃过。"}]}]);